pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(string memory name_, string memory tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) internal {
        vm.assume(itemsRemaining > 0);
        vm.assume(itemPrice > 0);
        uint256 tokenId;
        try c.uniqueTokensOutstanding() returns (uint256 __r) { tokenId = __r; } catch { return; }
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {} catch { return; }
        bool reverted;
        try c.safeTransferFrom(address(this), address(this), tokenId, 1, "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(string memory name_, string memory tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public {
        _run(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);
    }

    receive() external payable {}
}
